            R("Profile", "Perfil", "Perfil", "Profil", "Profil", "Profil", "Profil", "Hồ sơ"),
            R("Profile {0}", "Perfil {0}", "Perfil {0}", "Profil {0}", "Profil {0}", "Profil {0}", "Profil {0}", "Hồ sơ {0}"),
